theory:
### Contracts and polymorphism

Interfaces define capabilities without a single inheritance tree; a type may implement many interfaces. Explicit interface implementation hides members unless the reference is typed as that interface—useful when names collide or you want a cleaner public surface.

Default interface members (C# 8+) let you evolve contracts with optional implementations, but think carefully about versioning across assemblies.

### IDisposable and async

`IDisposable` (and `IAsyncDisposable`) represent resources beyond memory: file handles, network connections, database contexts. `using` and `await using` compile to try/finally with `Dispose`/`DisposeAsync` calls.

### Generic constraints

`where T : ISomething` constrains type parameters; combined with **covariance/contravariance** on interfaces (`IEnumerable<out T>`, `IComparer<in T>`), you can express flexible APIs while keeping static typing.

```csharp
using System;
using System.Threading.Tasks;

interface ILogger
{
    void Log(string message) => Console.WriteLine(message);
}

interface IAsyncWorker
{
    Task<int> ComputeAsync();
}
```

exercises.solution:
var rect = new Rectangle(3, 4);
Console.WriteLine(rect.Area());

interface IShape { double Area(); }
record Rectangle(double Width, double Height) : IShape
{
    public double Area() => Width * Height;
}

IWriter w = new Logger();
var n = w.Write(System.Text.Encoding.UTF8.GetBytes("hello"));
Console.Write($"{n} hello");

interface IWriter { int Write(byte[] data); }
class Logger : IWriter
{
    public int Write(byte[] data)
    {
        return data.Length;
    }
}

IShape c = new Circle(5), r = new Rectangle(3, 4);
Console.WriteLine(c.Area() > r.Area() ? c.Area() : r.Area());

interface IShape { double Area(); }
record Circle(double Radius) : IShape { public double Area() => Math.PI * Radius * Radius; }
record Rectangle(double Width, double Height) : IShape { public double Area() => Width * Height; }

IDescribable d = new Person("Alice");
Console.WriteLine(((Person)d).Name);

record Person(string Name) : IDescribable { public string Describe() => "Person: " + Name; }
interface IDescribable { string Describe(); }

DescribeAny(42);
DescribeAny("hello");

static void DescribeAny(object x)
{
    switch (x)
    {
        case int i: Console.WriteLine($"int: {i}"); break;
        case string s: Console.WriteLine($"string: {s}"); break;
    }
}

